 const d=ctx.drafts?.preparation||{},g=gang(ctx,p),role=p?.userId===r?.hostId?'attacker':'defender',source=missionRows(ctx.c,'crewSelection').find(row=>row.id===r?.setup?.crewSelectionId),spec=source?.rule_data?.both||source?.rule_data?.[role];
