 return {source,spec,role,saved,chosen,random,reinforcements,chosenIds,quota,exact,valid,fighters,eligibleIds,hasDraw:random!==0||reinforcements>0,requiresDraw:random!==0||reinforcements>0||spec.chosen==='D3'};
