  const result=await request(ctx,query,'GET',undefined,read.controller.signal);if(!currentRead(ctx,read))return false;
  ctx.players=result.players||[];ctx.rooms=result.rooms||[];acceptRegistration(ctx,result.registration);if(!automatic)observeMembership(ctx,result);ctx.unavailableReason=result.unavailableReason||null;ctx.serverTime=result.serverTime||new Date().toISOString();ctx.synced=now();ctx.liveFailures=0;ctx.error=ctx.cache.membershipFailure?membershipRefreshError():ctx.cache.completionRefreshError||ctx.cache.playError||'';if(ctx.mutationError?.action==='register-gang'&&registeredGangs(ctx).some(g=>g.sourceGangId===ctx.registrationDraft.sourceGangId)){ctx.mutationError=null;ctx.cache.errors.delete('new');ctx.notice=T('Your gang registration is confirmed.','내 갱 등록을 확인했습니다.');registeredCallback(ctx,{registration:ctx.registration,registeredGang:registeredGangs(ctx).find(g=>g.sourceGangId===ctx.registrationDraft.sourceGangId)});}
  if(ctx.selected){let next=ctx.rooms.find(r=>r.id===ctx.selected);if(!next){const detail=await request(ctx,'/'+encodeURIComponent(ctx.selected)+query,'GET',undefined,read.controller.signal);if(!currentRead(ctx,read))return false;next=detail.room;ctx.serverTime=detail.serverTime||ctx.serverTime;if(!automatic)absorb(ctx,detail,base);}acceptRoom(ctx,next);}
  if(!automatic)absorb(ctx,result,base);if(!currentRead(ctx,read))return false;
  const stable=viewSignature(ctx)===ctx.paintSignature,focused=ctx.host.contains(document.activeElement),sameOwn=oldOwn===JSON.stringify(self(ctx)?.preparation),sameReady=oldOwnReady===self(ctx)?.ready,setupChanged=oldSetup!==JSON.stringify(room(ctx)?.setup);if(setupChanged&&oldSetup!==undefined&&sameOwn){if(room(ctx)?.status==='preparing'&&self(ctx)){ctx.cache.prepSteps??=new Map();ctx.cache.prepSteps.set(room(ctx).id,1);}ctx.pendingSetupRevision=self(ctx)?.revision;ctx.draftRevision=oldSeat;ctx.notice=T('The shared setup changed. Review it above before marking ready.','공통 설정이 변경되었습니다. 위의 내용을 확인한 뒤 준비 완료하세요.');ctx.needsPaint=true;}
